import { describe, expect, it } from "vitest";
import { getImageProps } from "next/image";

import { normalizeTotpQrCode } from "@/lib/auth/totp-qr";

describe("TOTP QR code normalization", () => {
  it("encodes Supabase's raw multiline SVG without control characters", () => {
    const raw = `data:image/svg+xml;utf-8,<?xml version="1.0"?>
<!-- Generated by SVGo -->
<svg width="207" height="207" xmlns="http://www.w3.org/2000/svg"><path d="M0 0"/></svg>
`;

    const normalized = normalizeTotpQrCode(raw);

    expect(normalized).toMatch(/^data:image\/svg\+xml;charset=utf-8,/);
    expect(normalized).not.toContain("<svg");
    expect(normalized).not.toContain("\n");
    expect(decodeURIComponent(normalized.slice(normalized.indexOf(",") + 1))).toContain(
      '<svg width="207" height="207"',
    );
    expect(() => getImageProps({
      alt: "TOTP QR code",
      height: 207,
      src: normalized,
      unoptimized: true,
      width: 207,
    })).not.toThrow();
  });

  it("canonicalizes an already encoded SVG and preserves base64 SVG data", () => {
    const encoded = "data:image/svg+xml;charset=utf-8,%3Csvg%3E%3C%2Fsvg%3E";
    expect(normalizeTotpQrCode(encoded)).toBe(encoded);

    const base64 = "data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=";
    expect(normalizeTotpQrCode(` ${base64}\n`)).toBe(base64);
  });

  it("rejects non-SVG and malformed values", () => {
    expect(normalizeTotpQrCode("https://example.com/qr.svg")).toBe("");
    expect(normalizeTotpQrCode("data:image/png;base64,AAAA")).toBe("");
  });
});
